WITH seg AS (SELECT zone_id, weather_id, s.1 AS a, s.2 AS b FROM weather_timeline ARRAY JOIN [(tick, least(tick + minutes, 3110400)), (0, greatest(tick + minutes - 3110400, 0))] AS s WHERE minutes > 0 AND s.2 > s.1), cov AS (SELECT zone_id, sum(greatest(0, b - greatest(a, before))) AS covered FROM (SELECT zone_id, a, b, max(b) OVER (PARTITION BY zone_id ORDER BY a, b ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS before FROM seg) GROUP BY zone_id), mix AS (SELECT zone_id, arrayReverseSort(x -> x[2], groupArray([toInt64(weather_id), toInt64(m)])) AS mix FROM (SELECT zone_id, weather_id, sum(b - a) AS m FROM seg GROUP BY zone_id, weather_id) GROUP BY zone_id), cell AS (SELECT zone_id, arraySort(groupArray([toInt64(k), toInt64(w)])) AS cells FROM (SELECT zone_id, k, argMax(weather_id, m) AS w FROM (SELECT zone_id, weather_id, k, least(b, (k + 1) * 8640) - greatest(a, k * 8640) AS m FROM seg ARRAY JOIN range(intDiv(a, 8640), intDiv(b - 1, 8640) + 1) AS k) GROUP BY zone_id, k) GROUP BY zone_id) SELECT t.zone_id AS zone, any(zn.name) AS zone_name, count() AS starts, countIf(t.minutes > 0) AS periods, countIf(length(t.weathers) > 1 OR length(t.lengths) > 1) AS disagree, coalesce(any(cov.covered), 0) / 3110400 AS coverage, coalesce(any(mix.mix), []) AS mix, coalesce(any(cell.cells), []) AS cells FROM weather_timeline t LEFT JOIN (SELECT id, name FROM zone_names WHERE release = (SELECT max(release) FROM captures)) zn ON zn.id = t.zone_id LEFT JOIN cov ON cov.zone_id = t.zone_id LEFT JOIN mix ON mix.zone_id = t.zone_id LEFT JOIN cell ON cell.zone_id = t.zone_id GROUP BY t.zone_id ORDER BY coverage DESC, zone_name, zone
